#!/usr/bin/env bash
# check_dashboard_typecheck.sh — apps/dashboard-next için tip + derleme kapıları.
#
# setup-pre-commit skill'inin "commit-anı typecheck" hedefinin zincir-uyarlaması
# (Husky yerine mevcut pre-commit zinciri). Dört katman var:
#
#   0) Prisma ön-koşulu — CI `dashboard-smoke` sırasının AYNISI: istemci
#      yok/bayatsa `prisma generate` (yer tutucu DATABASE_URL) + CI'ın
#      doğrulama assert'leri (client.ts/internal/class.ts/enums.ts, >=5 dosya,
#      "code generated by Prisma" imzası) — CI bunları cache-hit'te bile koşar.
#      Bu adım tsc'DEN ÖNCE gelir: `lib/trend-db.ts` generated client'ı TS
#      kaynağı olarak içe aktarır; istemci yokken tsc sahte kırmızı verir ve
#      dosya CI'da yeşil olabilir. trend-db bağımlılıkları yoksa SKIP
#      (ortam-yok ≠ kod-bozuk); üretim/doğrulama tutmazsa fail-closed.
#
#   1) `tsc --noEmit`  — GÖNDERİLEN kodun tip denetimi (READ-ONLY: emit yok).
#      node_modules/tsconfig yoksa SKIP (exit 0) — ortam-bağımlı kapı ortam
#      yoksa bloke etmez (zincirin SKIP-kültürü).
#
#   2) `test-d/run_type_tests.py` — SÖZLEŞME denetimi: pozitif `Assert<Equal<..>>`
#      iddiaları + `@ts-expect-error` negatif iddialar. İlk katman "bu atama
#      geçiyor mu" diye sorar; bu katman "sözleşme hâlâ AYNI mı" diye sorar.
#      İkincisi olmadan bir union'a varyant eklenmesi, bir alan adı değişmesi ya
#      da bir fallback'in düşmesi derlemeden geçer ve sessizce runtime'a sızar.
#      Koşucu kendi ön-koşullarını denetler: tsc/tsconfig yoksa SKIP eder.
#
#   3) `npm run build` — CI'ın `dashboard-smoke` job'ındaki komutun AYNISI
#      (`next build`, CI=true ile). `tsc --noEmit` Next'e özgü hataları
#      yakalamaz: server/client sınırı, Turbopack modül çözümü, CSS/PostCSS
#      hattı ve route prerender hataları yalnız build'de görünür. next binary
#      yoksa SKIP (ortam-bağımlı); build hatası fail-closed bloke eder.
#
# Hepsi fail-closed: bulgu varsa commit bloke olur.
#
# Tracked-READ-ONLY sözleşmesi: `next build` `.next/` + `tsconfig.tsbuildinfo`
# üretir (ikisi de gitignored), ama tracked `next-env.d.ts` ve `tsconfig.json`
# dosyalarını da yeniden yazabilir. Build öncesi halleri geçici dizine alınır;
# build biterken (hata/kesinti dahil) fark varsa geri yazılır — commit anında
# ağaçta build kaynaklı bir tracked değişiklik bırakılmaz. `prisma generate`
# de yalnız gitignored `apps/trend-db/generated/`i yazar; tracked dosyaya
# dokunmaz (ölçüldü: generate sonrası çıktı birebir aynıydı).
set -euo pipefail
REPO="$(cd "$(dirname "$0")/../.." && pwd)"
APP="$REPO/apps/dashboard-next"

if [ ! -x "$APP/node_modules/.bin/tsc" ] || [ ! -f "$APP/tsconfig.json" ]; then
  echo "check-dashboard-typecheck: tsc/tsconfig yok — SKIP"
  exit 0
fi

# ── 0) Prisma ön-koşulu — CI `dashboard-smoke` sırasının AYNISI ─────────────
# next build ve `tsc --noEmit`, `apps/trend-db/generated/client.ts`i TS
# kaynağı olarak derler ve `@prisma/client`'ı trend-db/node_modules'tan
# çözer. CI önce `prisma generate` koşar (yer tutucu DATABASE_URL) ve
# artefaktı cache-hit'te bile doğrular; yerelde bu adım atlanırsa commit-anı
# kapısı, CI'da yeşil olan bir ağaçta sahte kırmızı üretirdi.
TREND_DB="$REPO/apps/trend-db"
GENERATED="$TREND_DB/generated"
CI_DATABASE_URL="postgresql://ci:ci@127.0.0.1:5432/ci?sslmode=disable"

# CI'ın `Verify generated Prisma client` adımındaki assert'lerin aynısı.
prisma_client_ready() {
  [ -s "$GENERATED/client.ts" ] &&
    [ -s "$GENERATED/internal/class.ts" ] &&
    [ -s "$GENERATED/enums.ts" ] &&
    [ "$(find "$GENERATED" -type f 2>/dev/null | wc -l | tr -d ' ')" -ge 5 ] &&
    grep -q "code generated by Prisma" "$GENERATED/client.ts"
}

if [ ! -f "$TREND_DB/prisma/schema.prisma" ] ||
   [ ! -d "$TREND_DB/node_modules/@prisma/client" ] ||
   [ ! -x "$TREND_DB/node_modules/.bin/prisma" ]; then
  echo "check-dashboard-typecheck: trend-db bağımlılıkları eksik — SKIP (npm ci --prefix apps/trend-db)"
  exit 0
fi

if prisma_client_ready; then
  echo "check-dashboard-typecheck: Prisma istemcisi hazır (CI doğrulaması geçti)"
else
  echo "check-dashboard-typecheck: Prisma istemcisi yok/bayat — CI gibi üretiliyor"
  ( cd "$TREND_DB" && DATABASE_URL="$CI_DATABASE_URL" npx prisma generate )
fi

if ! prisma_client_ready; then
  echo "check-dashboard-typecheck: Prisma istemcisi CI sözleşmesini sağlamıyor (5 dosya + imza)" >&2
  exit 1
fi

cd "$APP"
node_modules/.bin/tsc --noEmit
echo "check-dashboard-typecheck: tsc OK"

TYPE_TESTS="SKIP"
if [ ! -f "$APP/test-d/run_type_tests.py" ]; then
  echo "check-dashboard-typecheck: tip-test koşucusu yok — SKIP (tip katmanı)"
else
  # Koşucunun kendi ayrıştırıcısı önce doğrulanır: parser sessizce bozulursa
  # (örn. direktifleri hiç bulamazsa) iddialar denetlenmeden "yeşil" görünürdü.
  python3 test-d/run_type_tests.py --selftest
  python3 test-d/run_type_tests.py
  TYPE_TESTS="OK"
  echo "check-dashboard-typecheck: tip-testleri OK"
fi

# ── 3) build — next binary yoksa yalnız bu katman SKIP ─────────────────────
if [ ! -x "$APP/node_modules/.bin/next" ] || [ ! -f "$APP/package.json" ]; then
  echo "check-dashboard-typecheck: next/package.json yok — SKIP (build katmanı)"
  exit 0
fi

# Next'in yeniden yazabildiği tracked dosyalar: build-öncesi hali sakla,
# çıkışta (başarı, hata, Ctrl-C) fark varsa geri yaz.
TMP="$(mktemp -d)"
restore_tracked() {
  for f in next-env.d.ts tsconfig.json; do
    if [ -f "$TMP/$f" ] && ! cmp -s "$APP/$f" "$TMP/$f"; then
      cp "$TMP/$f" "$APP/$f"
      echo "check-dashboard-typecheck: $f build sırasında yeniden yazıldı — geri alındı"
    fi
  done
}
trap 'restore_tracked; rm -rf "$TMP"' EXIT
for f in next-env.d.ts tsconfig.json; do
  if [ -f "$APP/$f" ]; then
    cp "$APP/$f" "$TMP/$f"
  fi
done

set +e
# CI=true: GitHub Actions build ortamının aynısı (Next'in CI dalları, ör.
# etkileşimsiz/telemetrisiz davranış, yerelde sessizce farklılaşmasın).
CI=true NEXT_TELEMETRY_DISABLED=1 npm run build
build_rc=$?
set -e

if [ "$build_rc" -ne 0 ]; then
  echo "check-dashboard-typecheck: next build FAIL (rc=$build_rc)" >&2
  exit "$build_rc"
fi
echo "check-dashboard-typecheck: next build OK"
echo "check-dashboard-typecheck: OK (tsc + tip-testleri=$TYPE_TESTS + next build)"
